114	// nexusImageRef is the one place that builds the reference of an image of a
115	// repository of the bench Nexus ("docker-hosted" or "docker-proxy"). Today it is
116	// the path routing on the HTTP NodePort (H-PATH): 127.0.0.1:<HTTPNodePort>/
117	// <repository>/<name>:<tag>. Step 12 settles whether the instance serves it.
118	func nexusImageRef(p Params, repository string, img DatasetImage) ImageRef {
119		return ImageRef{
120			Transport: "docker",
121			Location:  seedLoopbackHost + ":" + strconv.Itoa(p.HTTPNodePort) + "/" + repository + "/" + img.Name + ":" + img.Tag,
122		}
123	}
124	
125	// upstreamImageRef is the reference of an image in the bench upstream reached
126	// through the port-forward at local ("127.0.0.1:<port>"): <local>/<name>:<tag>.
127	func upstreamImageRef(local string, img DatasetImage) ImageRef {
128		return ImageRef{Transport: "docker", Location: local + "/" + img.Name + ":" + img.Tag}
129	}
