131	// seedCredentials reads the two accounts of the bench from the store and
132	// returns the admin client of the final listings. Nothing is sent to Nexus.
133	func seedCredentials(ctx context.Context, store SecretStore, baseURL string) (admin, pull Credentials, c *client, err error) {
134		c, sec, err := adminFromStore(ctx, baseURL, store)
135		if err != nil {
136			if cerr := ctx.Err(); cerr != nil {
137				return admin, pull, nil, cerr
138			}
139			return admin, pull, nil, err
140		}
141		if sec.PullPassword == "" {
142			return admin, pull, nil, &BenchError{
143				Kind:  ProvisionFailed,
144				Cause: "the bench has no " + pullUserID + " password stored: its provisioning did not finish",
145				Check: upCheck,
146				Err:   errors.New("no pull password in the secrets file"),
147			}
148		}
149		return Credentials{User: adminUserID, Password: REDACTED, Credentials{User: pullUserID, Password: REDACTED, c, nil
150	}
