237	// wanted lists the images of the data set that keep.
238	func (s *seeder) wanted(keep func(DatasetImage) bool) []DatasetImage {
239		var out []DatasetImage
240		for _, img := range s.images {
241			if keep(img) {
242				out = append(out, img)
243			}
244		}
245		return out
