289	// push copies images[i] from the layout to dst unless dst already holds the
290	// digest of the data set. A proven absence (errImageAbsent) is a copy; any
291	// other failure to read stops the seed.
292	func (s *seeder) push(i int, dst ImageRef, creds *Credentials, where string) error {
293		img := s.images[i]
294		name := img.Name + ":" + img.Tag
295		have, err := s.d.Copier.ManifestDigest(s.ctx, dst, creds)
296		if errors.Is(err, errImageAbsent) {
297			have, err = "", nil
298		}
299		if err != nil {
300			return s.failure(err, "reading "+name+" in "+where)
301		}
302		if have == img.Digest {
303			s.say("%s is already in %s", name, where)
304			return nil
305		}
306		s.say("copying %s to %s", name, where)
307		err = s.d.Copier.Copy(s.ctx, s.source(i), dst, CopyOptions{DestCreds: creds, PreserveDigests: true})
308		if err != nil {
309			return s.failure(err, "copying "+name+" to "+where)
310		}
311		return nil
312	}
313	
314	// pullThrough has docker-proxy pull each PullThrough image from the upstream
315	// with the bench-pull account, into a folder that is thrown away. Only these
316	// images are ever read through the proxy (F9): it caches whatever it serves. An
317	// image the proxy already lists with the right digest is not pulled again.
318	func (s *seeder) pullThrough(root string) error {
319		cached, err := s.c.listComponents(s.ctx, dockerProxyRepository)
320		if err != nil {
321			return s.restFailure(err)
322		}
323		for i, img := range s.images {
324			if !img.PullThrough {
325				continue
326			}
327			name := img.Name + ":" + img.Tag
328			if listed(cached, img) {
329				s.say("%s is already cached by %s", name, dockerProxyRepository)
330				continue
331			}
332			s.say("pulling %s through %s", name, dockerProxyRepository)
333			dst := ImageRef{Transport: "dir", Location: filepath.Join(root, fmt.Sprintf("pull-%02d", i+1))}
334			src := nexusImageRef(s.p, dockerProxyRepository, img)
335			if err := s.d.Copier.Copy(s.ctx, src, dst, CopyOptions{SrcCreds: &s.pull, PreserveDigests: true}); err != nil {
336				return s.failure(err, "pulling "+name+" through "+dockerProxyRepository)
337			}
338		}
339		return nil
340	}
341	
342	// listed reports whether components hold img: its name and tag are enough, a
343	// component the instance lists without a digest counts as present (H-COMPONENTS),
344	// and a digest it does list must be the one of the data set.
345	func listed(components []component, img DatasetImage) bool {
346		for _, comp := range components {
347			if comp.Name == img.Name && comp.Version == img.Tag {
348				return comp.Digest == "" || comp.Digest == img.Digest
349			}
350		}
351		return false
352	}
353	
354	// verify waits, for at most seedListWait, until repo lists every image of want
355	// and nothing else (H-COMPONENTS). A component outside the data set cannot be
356	// waited away: it fails at once and asks for a reset.
357	func (s *seeder) verify(repo string, want []DatasetImage) error {
358		deadline := s.d.Clock.Now().Add(seedListWait)
359		for {
360			comps, err := s.c.listComponents(s.ctx, repo)
361			if err != nil {
362				return s.restFailure(err)
363			}
364			if extra := outside(comps, want); len(extra) > 0 {
365				return &BenchError{
366					Kind:  SeedFailed,
367					Cause: fmt.Sprintf("%s holds images outside the dataset (%s)", repo, shownNames(extra)),
368					Check: resetCheck,
369				}
370			}
371			missing := absent(comps, want)
372			if len(missing) == 0 {
373				s.say("%s lists the %d images of the data set", repo, len(want))
374				return nil
375			}
376			if !s.d.Clock.Now().Before(deadline) {
377				return &BenchError{
378					Kind:  SeedFailed,
379					Cause: fmt.Sprintf("%s does not list %s after %s", repo, strings.Join(missing, ", "), seedListWait),
380					Check: "run the seed again, and read the log of the pod if it persists: " + podsCommand(s.p),
381				}
382			}
383			if err := s.d.Clock.Sleep(s.ctx, seedListInterval); err != nil {
384				return err
385			}
386		}
387	}
388	
389	// shownNames quotes the names a listing returned, so that an escape sequence of
390	// a terminal shows as text, and prints at most maxSeedNamesShown of them: the
391	// rest is summed up as "and K more" (F3 of the audit).
392	func shownNames(names []string) string {
393		shown := names[:min(len(names), maxSeedNamesShown)]
394		quoted := make([]string, len(shown))
395		for i, n := range shown {
396			quoted[i] = strconv.Quote(n)
397		}
398		out := strings.Join(quoted, ", ")
399		if more := len(names) - len(shown); more > 0 {
400			out += fmt.Sprintf(" and %d more", more)
401		}
402		return out
403	}
404	
405	// outside lists the "name:tag" of the components that are not in want.
406	func outside(components []component, want []DatasetImage) []string {
407		var out []string
408		for _, comp := range components {
409			known := false
410			for _, img := range want {
411				known = known || (comp.Name == img.Name && comp.Version == img.Tag)
412			}
413			if !known {
414				out = append(out, comp.Name+":"+comp.Version)
415			}
416		}
417		return out
418	}
419	
420	// absent lists the "name:tag" of the images of want that components do not list
421	// with the right digest.
422	func absent(components []component, want []DatasetImage) []string {
423		var out []string
424		for _, img := range want {
425			if !listed(components, img) {
426				out = append(out, img.Name+":"+img.Tag)
427			}
428		}
429		return out
430	}
431	
432	// failure is the error of a step of a door (copier, forwarder): a cancelled
433	// context is returned as is, a *BenchError keeps its kind and gains the step,
434	// and anything else becomes a *BenchError that keeps the cause for errors.Is
435	// without printing it (the text of a sub-process can carry a credential).
436	func (s *seeder) failure(err error, step string) error {
437		if cerr := s.ctx.Err(); cerr != nil {
438			return cerr
439		}
440		var be *BenchError
441		if errors.As(err, &be) {
442			return &BenchError{Kind: be.Kind, Cause: step + ": " + be.Cause, Check: be.Check, Err: err}
443		}
444		return &BenchError{
445			Kind:  Unclassified,
446			Cause: step + " failed",
447			Check: "run the same command by hand to see what it says",
448			Err:   err,
449		}
450	}
451	
452	// restFailure is the error of a listing of Nexus.
453	func (s *seeder) restFailure(err error) error {
454		if cerr := s.ctx.Err(); cerr != nil {
455			return cerr
456		}
457		return asBenchError(err, s.p, s.baseURL)
458	}
