2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"os"
9		"path/filepath"
10		"strconv"
11		"strings"
12		"time"
13	)
14	
15	const (
16		// upstreamServiceName and upstreamServicePort are the Service of the bench
17		// upstream registry and the port the port-forward reaches.
18		upstreamServiceName = upstreamDeployment
19		upstreamServicePort = 5000
20	
21		// seedListWait bounds the wait for a repository to list what the seed put in
22		// it (H-COMPONENTS), and seedListInterval separates two readings.
23		seedListWait     = 30 * time.Second
24		seedListInterval = 2 * time.Second
25	
26		// seedLoopbackHost is the only host the port-forward may be reached on.
27		seedLoopbackHost = "127.0.0.1"
28	
29		// maxSeedNamesShown bounds the names of components a message prints, the rest
30		// being summed up as "and K more" (F3 of the audit).
31		maxSeedNamesShown = 5
32	
33		// resetCheck is what a repository that holds more than the data set asks.
34		resetCheck = "run `mise run nexus-bench:reset` to bring the bench back to its initial state"
35	)
36	
37	// SeedDeps are the doors Seed goes through: the cluster (to read the upstream),
38	// the port-forward to the upstream, the image copier, the clock of the bounded
39	// wait and the stored secrets.
40	type SeedDeps struct {
41		Runner    Runner
42		Forwarder PortForwarder
43		Copier    ImageCopier
44		Clock     Clock
45		Store     SecretStore
46	}
47	
48	// SeedResult is what Seed leaves in place: the data set, every digest filled,
49	// PullThrough true exactly for the images now cached in docker-proxy.
50	type SeedResult struct{ Images []DatasetImage }
51	
52	// Seed puts the data set (D-I) in place, in this order: the stored credentials,
53	// the state of the upstream (read only), the OCI layout in a temporary folder,
54	// the port-forward to the upstream and the upstream images, the end of the
55	// port-forward, the docker-hosted images, the pull-through of the PullThrough
56	// images by docker-proxy, and the two listings, which must hold the data set and
57	// nothing else. An image is copied only when the digest read at its destination
58	// differs from the one of the data set, so a second run copies nothing.
59	//
60	// Seed never scales, applies or writes to Nexus, and it never restores a cut
61	// upstream (NX-02b): a cut, missing or starting upstream is a SeedFailed before
62	// the first copy. Docker-proxy is read only for the PullThrough images (F9): a
63	// read of mirror/uncached through it would cache it, and only reset removes
64	// that. Every failure is a *BenchError whose cause stays reachable with
65	// errors.Is and is never printed, but a cancelled context, which is returned
66	// as is. A nil out discards the progress lines ("seed: ...", no password).
67	func Seed(ctx context.Context, d SeedDeps, baseURL string, p Params, out io.Writer) (SeedResult, error) {
68		if out == nil {
69			out = io.Discard
70		}
71		if err := ctx.Err(); err != nil {
72			return SeedResult{}, err
73		}
74		admin, pull, c, err := seedCredentials(ctx, d.Store, baseURL)
75		if err != nil {
76			return SeedResult{}, err
77		}
78		defer c.closeIdle()
79		if err := requireSeedableUpstream(ctx, d.Runner, p); err != nil {
80			return SeedResult{}, err
81		}
82	
83		images := Dataset()
84		s := &seeder{ctx: ctx, d: d, p: p, out: out, c: c, baseURL: baseURL, admin: admin, pull: pull, images: images}
85		root, err := os.MkdirTemp("", "nexus-bench-seed-")
86		if err != nil {
87			return SeedResult{}, &BenchError{
88				Kind:  SeedFailed,
89				Cause: "the temporary folder of the seed cannot be created",
90				Check: "check that TMPDIR is a folder this user can write to",
91				Err:   err,
92			}
93		}
94		defer func() { _ = os.RemoveAll(root) }()
95		if err := s.writeLayout(root); err != nil {
96			return SeedResult{}, err
97		}
98		steps := []func() error{
99			s.seedUpstream,
100			s.seedHosted,
101			func() error { return s.pullThrough(root) },
102			func() error { return s.verify(dockerProxyRepository, s.wanted(isPullThrough)) },
103			func() error { return s.verify(dockerHostedRepository, s.wanted(isHosted)) },
104		}
105		for _, step := range steps {
106			if err := step(); err != nil {
107				return SeedResult{}, err
108			}
109		}
110		s.say("the data set is in place: %d images", len(images))
111		return SeedResult{Images: images}, nil
112	}
113	
114	// nexusImageRef is the one place that builds the reference of an image of a
115	// repository of the bench Nexus ("docker-hosted" or "docker-proxy"). Today it is
116	// the path routing on the HTTP NodePort (H-PATH): 127.0.0.1:<HTTPNodePort>/
117	// <repository>/<name>:<tag>. Step 12 settles whether the instance serves it.
118	func nexusImageRef(p Params, repository string, img DatasetImage) ImageRef {
119		return ImageRef{
120			Transport: "docker",
121			Location:  seedLoopbackHost + ":" + strconv.Itoa(p.HTTPNodePort) + "/" + repository + "/" + img.Name + ":" + img.Tag,
122		}
123	}
124	
125	// upstreamImageRef is the reference of an image in the bench upstream reached
126	// through the port-forward at local ("127.0.0.1:<port>"): <local>/<name>:<tag>.
127	func upstreamImageRef(local string, img DatasetImage) ImageRef {
128		return ImageRef{Transport: "docker", Location: local + "/" + img.Name + ":" + img.Tag}
129	}
130	
131	// seedCredentials reads the two accounts of the bench from the store and
132	// returns the admin client of the final listings. Nothing is sent to Nexus.
133	func seedCredentials(ctx context.Context, store SecretStore, baseURL string) (admin, pull Credentials, c *client, err error) {
134		c, sec, err := adminFromStore(ctx, baseURL, store)
135		if err != nil {
136			if cerr := ctx.Err(); cerr != nil {
137				return admin, pull, nil, cerr
138			}
139			return admin, pull, nil, err
140		}
141		if sec.PullPassword == "" {
142			return admin, pull, nil, &BenchError{
143				Kind:  ProvisionFailed,
144				Cause: "the bench has no " + pullUserID + " password stored: its provisioning did not finish",
145				Check: upCheck,
146				Err:   errors.New("no pull password in the secrets file"),
147			}
148		}
149		return Credentials{User: adminUserID, Password: REDACTED, Credentials{User: pullUserID, Password: REDACTED, c, nil
150	}
151	
152	// requireSeedableUpstream refuses what the seed cannot fill: an upstream URL the
153	// bench did not deploy (the proxy would not read what the seed pushes), and an
154	// upstream that is missing, cut or still starting. It writes nothing: bringing a
155	// cut upstream back is NX-02b.
156	func requireSeedableUpstream(ctx context.Context, r Runner, p Params) error {
157		if !p.UpstreamIsBench() {
158			return &BenchError{
159				Kind:  SeedFailed,
160				Cause: fmt.Sprintf("%s points at an upstream the bench did not deploy, and the seed pushes to the upstream of the bench only", envUpstreamURL),
161				Check: "unset " + envUpstreamURL + " to use the bench upstream",
162			}
163		}
164		state, err := ReadUpstream(ctx, r, p)
165		if err != nil {
166			return err
167		}
168		switch state {
169		case UpstreamMissing:
170			return &BenchError{
171				Kind:  SeedFailed,
172				Cause: fmt.Sprintf("the upstream %s does not exist in namespace %q", upstreamDeployment, p.Namespace),
173				Check: "run `mise run nexus-bench:up`, which deploys it",
174			}
175		case UpstreamCut:
176			return &BenchError{
177				Kind:  SeedFailed,
178				Cause: "the upstream is cut",
179				Check: "run `mise run nexus-bench:restore-upstream`, then the seed again",
180			}
181		case UpstreamStarting:
182			return &BenchError{
183				Kind:  SeedFailed,
184				Cause: "the upstream is still starting",
185				Check: "wait for its pod to be Ready (" + podsCommand(p) + "), then run the seed again",
186			}
187		}
188		return nil
189	}
190	
191	// seeder is one run of Seed.
192	type seeder struct {
193		ctx     context.Context
194		d       SeedDeps
195		p       Params
196		out     io.Writer
197		c       *client
198		baseURL string
199		admin   Credentials
200		pull    Credentials
201		images  []DatasetImage // Dataset(), digests filled
202		layout  string         // the OCI layout folder
203		refs    []string       // the layout reference of images[i]
204	}
205	
206	func (s *seeder) say(format string, args ...any) {
207		_, _ = fmt.Fprintf(s.out, "seed: "+format+"\n", args...)
208	}
209	
210	// writeLayout writes the data set as an OCI layout under root.
211	func (s *seeder) writeLayout(root string) error {
212		s.layout = filepath.Join(root, "layout")
213		err := os.Mkdir(s.layout, 0o700)
214		if err == nil {
215			s.refs, err = WriteLayout(s.layout, s.images)
216		}
217		if err != nil {
218			return &BenchError{
219				Kind:  SeedFailed,
220				Cause: "the OCI layout of the data set cannot be written",
221				Check: "check that TMPDIR has room and is writable",
222				Err:   err,
223			}
224		}
225		return nil
226	}
227	
228	// source is the layout reference of images[i].
229	func (s *seeder) source(i int) ImageRef {
230		return ImageRef{Transport: "oci", Location: s.layout + ":" + s.refs[i]}
231	}
232	
233	func isPullThrough(img DatasetImage) bool { return img.PullThrough }
234	
235	func isHosted(img DatasetImage) bool { return img.Location == LocationHosted }
236	
237	// wanted lists the images of the data set that keep.
238	func (s *seeder) wanted(keep func(DatasetImage) bool) []DatasetImage {
239		var out []DatasetImage
240		for _, img := range s.images {
241			if keep(img) {
242				out = append(out, img)
243			}
244		}
245		return out
246	}
247	
248	// seedUpstream pushes the upstream images through a port-forward that is always
249	// stopped before it returns.
250	func (s *seeder) seedUpstream() error {
251		local, stop, err := s.d.Forwarder.Forward(s.ctx, s.p.Namespace, upstreamServiceName, upstreamServicePort)
252		if err != nil {
253			return s.failure(err, "the port-forward to the upstream")
254		}
255		if stop != nil {
256			defer func() { _ = stop() }()
257		}
258		if !strings.HasPrefix(local, seedLoopbackHost+":") || !loopbackRegistry(local) {
259			return &BenchError{
260				Kind:  SeedFailed,
261				Cause: "the port-forward to the upstream is not on 127.0.0.1",
262				Check: "the bench pushes to a registry on the loopback only: check the kubectl on PATH",
263			}
264		}
265		for i, img := range s.images {
266			if img.Location != LocationUpstream {
267				continue
268			}
269			if err := s.push(i, upstreamImageRef(local, img), nil, "the upstream"); err != nil {
270				return err
271			}
272		}
273		return nil
274	}
275	
276	// seedHosted pushes the docker-hosted images with the admin account.
277	func (s *seeder) seedHosted() error {
278		for i, img := range s.images {
279			if img.Location != LocationHosted {
280				continue
281			}
282			if err := s.push(i, nexusImageRef(s.p, dockerHostedRepository, img), &s.admin, dockerHostedRepository); err != nil {
283				return err
284			}
285		}
286		return nil
287	}
288	
289	// push copies images[i] from the layout to dst unless dst already holds the
290	// digest of the data set. A proven absence (errImageAbsent) is a copy; any
291	// other failure to read stops the seed.
292	func (s *seeder) push(i int, dst ImageRef, creds *Credentials, where string) error {
293		img := s.images[i]
294		name := img.Name + ":" + img.Tag
295		have, err := s.d.Copier.ManifestDigest(s.ctx, dst, creds)
296		if errors.Is(err, errImageAbsent) {
297			have, err = "", nil
298		}
299		if err != nil {
300			return s.failure(err, "reading "+name+" in "+where)
301		}
302		if have == img.Digest {
303			s.say("%s is already in %s", name, where)
304			return nil
305		}
306		s.say("copying %s to %s", name, where)
307		err = s.d.Copier.Copy(s.ctx, s.source(i), dst, CopyOptions{DestCreds: creds, PreserveDigests: true})
308		if err != nil {
309			return s.failure(err, "copying "+name+" to "+where)
310		}
311		return nil
312	}
313	
314	// pullThrough has docker-proxy pull each PullThrough image from the upstream
315	// with the bench-pull account, into a folder that is thrown away. Only these
316	// images are ever read through the proxy (F9): it caches whatever it serves. An
317	// image the proxy already lists with the right digest is not pulled again.
318	func (s *seeder) pullThrough(root string) error {
319		cached, err := s.c.listComponents(s.ctx, dockerProxyRepository)
320		if err != nil {
321			return s.restFailure(err)
322		}
323		for i, img := range s.images {
324			if !img.PullThrough {
325				continue
326			}
327			name := img.Name + ":" + img.Tag
328			if listed(cached, img) {
329				s.say("%s is already cached by %s", name, dockerProxyRepository)
330				continue
331			}
332			s.say("pulling %s through %s", name, dockerProxyRepository)
333			dst := ImageRef{Transport: "dir", Location: filepath.Join(root, fmt.Sprintf("pull-%02d", i+1))}
334			src := nexusImageRef(s.p, dockerProxyRepository, img)
335			if err := s.d.Copier.Copy(s.ctx, src, dst, CopyOptions{SrcCreds: &s.pull, PreserveDigests: true}); err != nil {
336				return s.failure(err, "pulling "+name+" through "+dockerProxyRepository)
337			}
338		}
339		return nil
340	}
341	
342	// listed reports whether components hold img: its name and tag are enough, a
343	// component the instance lists without a digest counts as present (H-COMPONENTS),
344	// and a digest it does list must be the one of the data set.
345	func listed(components []component, img DatasetImage) bool {
346		for _, comp := range components {
347			if comp.Name == img.Name && comp.Version == img.Tag {
348				return comp.Digest == "" || comp.Digest == img.Digest
349			}
350		}
351		return false
352	}
353	
354	// verify waits, for at most seedListWait, until repo lists every image of want
355	// and nothing else (H-COMPONENTS). A component outside the data set cannot be
356	// waited away: it fails at once and asks for a reset.
357	func (s *seeder) verify(repo string, want []DatasetImage) error {
358		deadline := s.d.Clock.Now().Add(seedListWait)
359		for {
360			comps, err := s.c.listComponents(s.ctx, repo)
361			if err != nil {
362				return s.restFailure(err)
363			}
364			if extra := outside(comps, want); len(extra) > 0 {
365				return &BenchError{
366					Kind:  SeedFailed,
367					Cause: fmt.Sprintf("%s holds images outside the dataset (%s)", repo, shownNames(extra)),
368					Check: resetCheck,
369				}
370			}
371			missing := absent(comps, want)
372			if len(missing) == 0 {
373				s.say("%s lists the %d images of the data set", repo, len(want))
374				return nil
375			}
376			if !s.d.Clock.Now().Before(deadline) {
377				return &BenchError{
378					Kind:  SeedFailed,
379					Cause: fmt.Sprintf("%s does not list %s after %s", repo, strings.Join(missing, ", "), seedListWait),
380					Check: "run the seed again, and read the log of the pod if it persists: " + podsCommand(s.p),
381				}
382			}
383			if err := s.d.Clock.Sleep(s.ctx, seedListInterval); err != nil {
384				return err
385			}
386		}
387	}
388	
389	// shownNames quotes the names a listing returned, so that an escape sequence of
390	// a terminal shows as text, and prints at most maxSeedNamesShown of them: the
391	// rest is summed up as "and K more" (F3 of the audit).
392	func shownNames(names []string) string {
393		shown := names[:min(len(names), maxSeedNamesShown)]
394		quoted := make([]string, len(shown))
395		for i, n := range shown {
396			quoted[i] = strconv.Quote(n)
397		}
398		out := strings.Join(quoted, ", ")
399		if more := len(names) - len(shown); more > 0 {
400			out += fmt.Sprintf(" and %d more", more)
401		}
402		return out
403	}
404	
405	// outside lists the "name:tag" of the components that are not in want.
406	func outside(components []component, want []DatasetImage) []string {
407		var out []string
408		for _, comp := range components {
409			known := false
410			for _, img := range want {
411				known = known || (comp.Name == img.Name && comp.Version == img.Tag)
412			}
413			if !known {
414				out = append(out, comp.Name+":"+comp.Version)
415			}
416		}
417		return out
418	}
419	
420	// absent lists the "name:tag" of the images of want that components do not list
421	// with the right digest.
422	func absent(components []component, want []DatasetImage) []string {
423		var out []string
424		for _, img := range want {
425			if !listed(components, img) {
426				out = append(out, img.Name+":"+img.Tag)
427			}
428		}
429		return out
430	}
431	
432	// failure is the error of a step of a door (copier, forwarder): a cancelled
433	// context is returned as is, a *BenchError keeps its kind and gains the step,
434	// and anything else becomes a *BenchError that keeps the cause for errors.Is
435	// without printing it (the text of a sub-process can carry a credential).
436	func (s *seeder) failure(err error, step string) error {
437		if cerr := s.ctx.Err(); cerr != nil {
438			return cerr
439		}
440		var be *BenchError
441		if errors.As(err, &be) {
442			return &BenchError{Kind: be.Kind, Cause: step + ": " + be.Cause, Check: be.Check, Err: err}
443		}
444		return &BenchError{
445			Kind:  Unclassified,
446			Cause: step + " failed",
447			Check: "run the same command by hand to see what it says",
448			Err:   err,
449		}
450	}
451	
452	// restFailure is the error of a listing of Nexus.
453	func (s *seeder) restFailure(err error) error {
454		if cerr := s.ctx.Err(); cerr != nil {
455			return cerr
456		}
457		return asBenchError(err, s.p, s.baseURL)
458	}
