127	// RunPreflight checks, with read-only kubectl calls, that op can go ahead, and
128	// returns what it learned. Nothing is written to the cluster, whatever the
129	// outcome: a failure here means no write was ever issued. The checks run in a
130	// fixed order and stop at the first failure, so nothing is asked of a cluster
131	// the context does not reach:
132	//
133	//  1. the parameters (no call at all)
134	//  2. the context is in the kubeconfig
135	//  3. the API server answers /readyz
136	//  4. the can-i questions of the operation
137	//  5. the namespace: absent, ours, or foreign
138	//  6. up only: no other Service holds one of our NodePorts
139	//  7. all but down and seed: the InternalIP of the node
140	//
141	// Every failure is a *BenchError.
142	func RunPreflight(ctx context.Context, r Runner, p Params, op Op) (PreflightResult, error) {
143		var res PreflightResult
144		if err := p.Validate(); err != nil {
145			return res, err
146		}
147		pf := preflight{r: r, p: p}
148		if err := pf.checkContext(ctx); err != nil {
149			return res, err
150		}
151		if err := pf.checkReachable(ctx); err != nil {
152			return res, err
153		}
154		for _, perm := range permissionsByOp[op] {
155			if err := pf.checkPermission(ctx, perm); err != nil {
156				return res, err
157			}
158		}
159		res, err := pf.checkNamespace(ctx, op)
160		if err != nil {
161			return res, err
162		}
163		if op == OpUp {
164			if err := pf.checkNodePorts(ctx); err != nil {
165				return res, err
166			}
167		}
168		// The seed reaches the registries through a port-forward on the loopback: it
169		// has no use for the node address and no can-i question covers get nodes.
170		if op != OpDown && op != OpSeed {
171			if res.NodeIP, err = pf.nodeIP(ctx); err != nil {
172				return res, err
173			}
174		}
175		return res, nil
176	}
177	
178	type preflight struct {
179		r Runner
180		p Params
181	}
182	
183	// local runs a call that does not reach the API server.
184	func (pf preflight) local(ctx context.Context, args ...string) (stdout, stderr string, err error) {
185		out, errOut, err := pf.r.Run(ctx, nil, args...)
186		return string(out), string(errOut), err
187	}
188	
189	// remote runs a call that reaches the API server, under a request timeout.
190	func (pf preflight) remote(ctx context.Context, args ...string) (stdout, stderr string, err error) {
191		return pf.local(ctx, slices.Concat(args, []string{requestTimeout})...)
192	}
193	
194	// command is the kubectl command line a user can run to repeat a call.
195	func (pf preflight) command(args ...string) string {
196		return "kubectl --context " + pf.p.Context + " " + strings.Join(args, " ")
197	}
198	
199	// failure turns a failed kubectl call into a BenchError whose kind comes from
200	// the stderr. Neither the stderr nor the sub-process error reaches the message.
201	func (pf preflight) failure(what string, args []string, stderr string, err error) *BenchError {
202		kind := classifyKubectl(stderr)
203		reason := "kubectl failed"
204		switch kind {
205		case Forbidden:
206			reason = "the API server refused the request (forbidden)"
207		case ClusterUnreachable:
208			reason = "the cluster did not answer"
209		}
210		return &BenchError{
211			Kind:  kind,
212			Cause: "could not " + what + ": " + reason,
213			Check: pf.command(args...),
214			Err:   err,
215		}
216	}
217	
218	func (pf preflight) checkContext(ctx context.Context) error {
219		args := []string{"config", "get-contexts", "-o", "name"}
220		out, errOut, err := pf.local(ctx, args...)
221		if err != nil {
222			return pf.failure("list the kubeconfig contexts", args, errOut, err)
223		}
224		for _, line := range strings.Split(out, "\n") {
225			if strings.TrimSpace(line) == pf.p.Context {
226				return nil
227			}
228		}
229		return &BenchError{
230			Kind:  ContextNotFound,
231			Cause: fmt.Sprintf("no kubeconfig context is named %q", pf.p.Context),
232			Check: "kubectl config get-contexts -o name, then set NEXUS_BENCH_CONTEXT to one of them",
233		}
234	}
235	
236	func (pf preflight) checkReachable(ctx context.Context) error {
237		args := []string{"get", "--raw", "/readyz"}
238		_, errOut, err := pf.remote(ctx, args...)
239		if err == nil {
240			return nil
241		}
242		// A refusal (an expired token, a 403) is not an absent cluster: say so.
243		// Anything else, classified or not, means the server did not answer.
244		if classifyKubectl(errOut) == Forbidden {
245			return pf.failure("reach the API server", args, errOut, err)
246		}
247		return &BenchError{
248			Kind:  ClusterUnreachable,
249			Cause: fmt.Sprintf("the API server of context %q does not answer /readyz", pf.p.Context),
250			Check: pf.command(args...),
251			Err:   err,
252		}
253	}
254	
255	// checkPermission asks "kubectl auth can-i". A "no" arrives on stdout with a
256	// non-zero exit, so the answer is read before the error.
257	func (pf preflight) checkPermission(ctx context.Context, perm permission) error {
258		args := []string{"auth", "can-i", perm.verb, perm.resource}
259		if perm.subresource != "" {
260			args = append(args, "--subresource="+perm.subresource)
261		}
262		where := "cluster-wide"
263		switch perm.scope {
264		case scopeNamespace:
265			args = append(args, "-n", pf.p.Namespace)
266			where = fmt.Sprintf("in namespace %q", pf.p.Namespace)
267		case scopeAll:
268			args = append(args, "-A")
269			where = "in all namespaces"
270		}
271		out, errOut, err := pf.remote(ctx, args...)
272		answer := strings.TrimSpace(out)
273		switch {
274		case strings.HasPrefix(answer, "no"):
275			return &BenchError{
276				Kind:  Forbidden,
277				Cause: fmt.Sprintf("the current user is not allowed to %s %s %s", perm.verb, perm.name(), where),
278				Check: pf.command(args...),
279				Err:   err,
280			}
281		case err == nil && strings.HasPrefix(answer, "yes"):
282			return nil
283		}
284		return pf.failure(fmt.Sprintf("check the permission to %s %s", perm.verb, perm.name()), args, errOut, err)
285	}
