287	// namespaceObject is the part of a Namespace the preflight reads.
288	type namespaceObject struct {
289		Metadata struct {
290			Labels map[string]string `json:"labels"`
291		} `json:"metadata"`
292	}
293	
294	func (pf preflight) checkNamespace(ctx context.Context, op Op) (PreflightResult, error) {
295		var res PreflightResult
296		ns := pf.p.Namespace
297		args := []string{"get", "namespace", ns, "-o", "json"}
298		out, errOut, err := pf.remote(ctx, args...)
299		switch {
300		case err != nil && isNotFound(errOut):
301			// Absent: only provision, status and seed need it.
302			if op == OpProvision || op == OpStatus || op == OpSeed {
303				return res, &BenchError{
304					Kind:  NamespaceMissing,
305					Cause: fmt.Sprintf("namespace %q does not exist", ns),
306					Check: pf.command(args[:3]...) + ", then run `mise run nexus-bench:up`",
307					Err:   err,
308				}
309			}
310			return res, nil
311		case err != nil:
312			return res, pf.failure(fmt.Sprintf("read the namespace %q", ns), args, errOut, err)
313		}
314	
315		var obj namespaceObject
316		if err := json.Unmarshal([]byte(out), &obj); err != nil {
317			return res, &BenchError{
318				Kind:  Unclassified,
319				Cause: fmt.Sprintf("kubectl answered with something that is not a Namespace for %q", ns),
320				Check: pf.command(args...),
321				Err:   err,
322			}
323		}
324		res.NamespaceExists = true
325		res.NamespaceOurs = obj.Metadata.Labels[managedByLabel] == managedByValue
326		if !res.NamespaceOurs {
327			return res, &BenchError{
328				Kind:  NamespaceForeign,
329				Cause: fmt.Sprintf("namespace %q exists but does not carry the label %s=%s, so the bench did not create it", ns, managedByLabel, managedByValue),
330				Check: pf.command("get", "namespace", ns, "--show-labels") + ", or choose another NEXUS_BENCH_NAMESPACE",
331			}
332		}
333		return res, nil
334	}
335	
336	// serviceList is the part of a Service list the preflight reads.
337	type serviceList struct {
338		Items []struct {
339			Metadata struct {
340				Name      string `json:"name"`
341				Namespace string `json:"namespace"`
342			} `json:"metadata"`
343			Spec struct {
344				Ports []struct {
345					NodePort int `json:"nodePort"`
346				} `json:"ports"`
347			} `json:"spec"`
348		} `json:"items"`
349	}
350	
351	// checkNodePorts reads every Service of the cluster: the list of taken
352	// NodePorts is not a constant (F1). Our own Service, in our namespace, may hold
353	// them: that is a second up.
354	func (pf preflight) checkNodePorts(ctx context.Context) error {
355		args := []string{"get", "services", "-A", "-o", "json"}
356		out, errOut, err := pf.remote(ctx, args...)
357		if err != nil {
358			return pf.failure("list the Services of the cluster", args, errOut, err)
359		}
360		var list serviceList
361		if err := json.Unmarshal([]byte(out), &list); err != nil {
362			return &BenchError{
363				Kind:  Unclassified,
364				Cause: "kubectl answered with something that is not a Service list",
365				Check: pf.command(args...),
366				Err:   err,
367			}
368		}
369		var taken []string
370		for _, svc := range list.Items {
371			if svc.Metadata.Namespace == pf.p.Namespace && svc.Metadata.Name == nexusServiceName {
372				continue
373			}
374			for _, port := range svc.Spec.Ports {
375				if port.NodePort == pf.p.HTTPNodePort || port.NodePort == pf.p.DockerNodePort {
376					taken = append(taken, fmt.Sprintf("%d is held by Service %s/%s", port.NodePort, svc.Metadata.Namespace, svc.Metadata.Name))
377				}
378			}
379		}
380		if len(taken) > 0 {
381			return &BenchError{
382				Kind:  NodePortTaken,
383				Cause: "NodePort " + strings.Join(taken, ", "),
384				Check: pf.command(args...) + ", then set NEXUS_BENCH_HTTP_NODEPORT and NEXUS_BENCH_DOCKER_NODEPORT to free ports",
385			}
386		}
387		return nil
388	}
