87	type componentPage struct {
88		Items             []componentItem `json:"items"`
89		ContinuationToken *string         `json:"continuationToken"`
90	}
91	
92	type componentItem struct {
93		Name    string           `json:"name"`
94		Version string           `json:"version"`
95		Assets  []componentAsset `json:"assets"`
96	}
97	
98	type componentAsset struct {
99		Path     string `json:"path"`
100		Checksum struct {
101			SHA256 string `json:"sha256"`
102		} `json:"checksum"`
103	}
104	
105	// listComponents lists the components of repo, following the continuation token
106	// until the last page; a token equal to the previous one is an error. A
107	// repository the instance does not know lists as no component. An error on any
108	// page drops what the earlier pages returned.
109	//
110	// H-COMPONENTS (to settle at step 12): a Docker component is one image tag, and
111	// the sha256 checksum of its asset under v2/<name>/manifests/<tag> is the digest
112	// of the manifest.
113	func (c *client) listComponents(ctx context.Context, repo string) ([]component, error) {
114		op := "list the components of " + repo
115		var out []component
116		token := ""
117		for page := 0; page < maxComponentPages; page++ {
118			query := url.Values{"repository": {repo}}
119			if token != "" {
120				query.Set("continuationToken", token)
121			}
122			var body componentPage
123			found, err := c.get(ctx, op, componentsPath, query, &body)
124			if err != nil {
125				return nil, err
126			}
127			if !found {
128				if page == 0 {
129					return nil, nil
130				}
131				return nil, &APIError{Op: op, Status: http.StatusNotFound}
132			}
133			if len(out)+len(body.Items) > maxListedComponents {
134				return nil, &tooManyError{Op: op}
135			}
136			for _, item := range body.Items {
137				out = append(out, component{Name: item.Name, Version: item.Version, Digest: manifestDigest(item)})
138			}
139			if body.ContinuationToken == nil || *body.ContinuationToken == "" {
140				return out, nil
141			}
142			// The same token as the previous page would repeat that page for ever.
143			if *body.ContinuationToken == token {
144				return nil, &decodeError{Op: op, Err: errors.New("the continuation token repeats")}
145			}
146			token = *body.ContinuationToken
147		}
148		return nil, &decodeError{Op: op, Err: errors.New("the continuation token never ends")}
149	}
150	
151	// manifestDigest returns "sha256:<hex>" of the manifest asset of item, or "" when
152	// the instance lists none. The asset of the tag itself wins over any other
153	// manifest asset (a digest-addressed one, for instance).
154	func manifestDigest(item componentItem) string {
155		digest := ""
156		for _, a := range item.Assets {
157			if a.Checksum.SHA256 == "" || !strings.Contains(a.Path, manifestMarker) {
158				continue
159			}
160			if strings.HasSuffix(a.Path, manifestMarker+item.Version) {
161				return "sha256:" + a.Checksum.SHA256
162			}
163			if digest == "" {
164				digest = "sha256:" + a.Checksum.SHA256
165			}
166		}
167		return digest
168	}
