741	// asBenchError turns what the client and the steps returned into the BenchError
742	// of D-F: RESTUnreachable for a call that got no answer, ProvisionFailed for the
743	// rest. A BenchError passes unchanged. The text it builds holds the operation and
744	// the status, never a URL, a body or a password; the original error stays in Err.
745	func asBenchError(err error, p Params, baseURL string) error {
746		var be *BenchError
747		if errors.As(err, &be) {
748			return err
749		}
750		pods := podsCommand(p)
751		logs := fmt.Sprintf("kubectl --context %s -n %s logs deploy/nexus", p.Context, p.Namespace)
752		var (
753			api       *APIError
754			transport *transportError
755			large     *tooLargeError
756			many      *tooManyError
757			decode    *decodeError
758		)
759		switch {
760		case errors.As(err, &transport):
761			return &BenchError{
762				Kind:  RESTUnreachable,
763				Cause: fmt.Sprintf("the Nexus REST API at %s did not answer (%s)", hostOf(baseURL), transport.Op),
764				Check: "check that the pod is Ready (" + pods + ") and that the NodePort answers from this machine",
765				Err:   err,
766			}
767		case errors.As(err, &api) && (api.Status == http.StatusUnauthorized || api.Status == http.StatusForbidden):
768			return &BenchError{
769				Kind:  ProvisionFailed,
770				Cause: "Nexus refused the bench account: " + api.Error(),
771				Check: "the admin password in the secrets file may not match the instance; run `mise run nexus-bench:down` then `mise run nexus-bench:up`",
772				Err:   err,
773			}
774		case errors.As(err, &api):
775			return &BenchError{Kind: ProvisionFailed, Cause: "Nexus refused a request: " + api.Error(), Check: "read the log of the pod: " + logs, Err: err}
776		case errors.As(err, &large):
777			return &BenchError{
778				Kind: ProvisionFailed, Cause: large.Error(),
779				Check: "check that " + hostOf(baseURL) + " is the Nexus REST API and not another service", Err: err,
780			}
781		case errors.As(err, &many):
782			return &BenchError{
783				Kind: ProvisionFailed, Cause: many.Error(),
784				Check: "the repository holds far more than the data set: " + resetCheck, Err: err,
785			}
786		case errors.As(err, &decode):
787			return &BenchError{
788				Kind: ProvisionFailed, Cause: decode.Error(),
789				Check: "compare the answer with /service/rest/swagger.json of the instance (H-REST); the version may differ from 3.98.1", Err: err,
790			}
791		}
792		return &BenchError{Kind: ProvisionFailed, Cause: "provisioning failed", Check: "read the log of the pod: " + logs, Err: err}
793	}
