795	// hostOf returns host:port of baseURL, without any user information, for a message.
796	func hostOf(baseURL string) string {
797		u, err := url.Parse(baseURL)
798		if err != nil || u.Host == "" {
799			return "the instance"
800		}
801		return u.Host
802	}
