653	// repositories returns the three Docker repositories, in the order they can be
654	// created: the group needs its members.
655	func (pv *provisioner) repositories() []repositorySpec {
656		storage := func(extra map[string]any) map[string]any {
657			s := map[string]any{"blobStoreName": defaultBlobStore, "strictContentTypeValidation": true}
658			for k, v := range extra {
659				s[k] = v
660			}
661			return s
662		}
663		// Anonymous pulls need the Docker API without a forced Basic auth. The hosted
664		// and the proxy are reached by path on the HTTP port (pathEnabled, H-PATH): it
665		// is null by default, and /v2/ then answers 404 there.
666		docker := func(extra map[string]any) map[string]any {
667			d := map[string]any{"v1Enabled": false, "forceBasicAuth": false}
668			for k, v := range extra {
669				d[k] = v
670			}
671			return d
672		}
673		return []repositorySpec{
674			{"hosted", dockerHostedRepository, map[string]any{
675				"name": dockerHostedRepository, "online": true,
676				"storage": storage(map[string]any{"writePolicy": "ALLOW"}),
677				"docker":  docker(map[string]any{"pathEnabled": true}),
678			}},
679			{"proxy", dockerProxyRepository, map[string]any{
680				"name": dockerProxyRepository, "online": true,
681				"storage": storage(nil),
682				"docker":  docker(map[string]any{"pathEnabled": true}),
683				"proxy": map[string]any{
684					"remoteUrl": pv.p.UpstreamURL, "contentMaxAge": repositoryMaxAgeMinutes, "metadataMaxAge": repositoryMaxAgeMinutes,
685				},
686				"dockerProxy":   map[string]any{"indexType": "REGISTRY"},
687				"negativeCache": map[string]any{"enabled": true, "timeToLive": repositoryMaxAgeMinutes},
688				"httpClient":    map[string]any{"blocked": false, "autoBlock": true},
689			}},
690			{"group", dockerGroupRepository, map[string]any{
691				"name": dockerGroupRepository, "online": true,
692				"storage": storage(nil),
693				"docker":  docker(map[string]any{"httpPort": dockerContainerPort}),
694				"group":   map[string]any{"memberNames": []string{dockerHostedRepository, dockerProxyRepository}},
695			}},
696		}
697	}
