699	func (pv *provisioner) ensureRepositories(ctx context.Context) error {
700		for _, repo := range pv.repositories() {
701			collection := dockerReposPath + "/" + repo.kind
702			found, err := pv.api.get(ctx, fmt.Sprintf("read the %s repository %s", repo.kind, repo.name), collection+"/"+repo.name, nil, nil)
703			if err != nil {
704				return err
705			}
706			verb, method, path, done := "create", http.MethodPost, collection, "created"
707			if found {
708				verb, method, path, done = "update", http.MethodPut, collection+"/"+repo.name, "updated"
709			}
710			op := fmt.Sprintf("%s the %s repository %s", verb, repo.kind, repo.name)
711			if repo.name == dockerGroupRepository && pv.proxyPending {
712				repo.config["group"] = map[string]any{"memberNames": []string{dockerHostedRepository}}
713			}
714			if err := pv.api.write(ctx, op, method, path, repo.config); err != nil {
715				if repo.name == dockerProxyRepository {
716					if explained := pv.privateUpstreamError(err); explained != nil {
717						return explained
718					}
719				}
720				var api *APIError
721				if repo.name != dockerProxyRepository || !errors.As(err, &api) || !api.RemoteURLBlocked {
722					return err
723				}
724				// The upstream is deployed by NX-02: until its host resolves, Nexus
725				// refuses the proxy. Say so and carry on without it; a later run adds it.
726				pv.proxyPending = !found
727				state := "left as it was"
728				if !found {
729					state = "left out"
730				}
731				pv.say("warning: Nexus refused the remote URL of %s: it cannot resolve the upstream host yet, so it was %s; run up again once the upstream exists", repo.name, state)
732				continue
733			}
734			pv.say("%s repository %s %s", repo.kind, repo.name, done)
735		}
736		return nil
737	}
