207	// adminClient settles which REDACTED the admin account has and returns a client
208	// that uses it. The candidates are the stored admin REDACTED, then the pending
209	// one (a change that was interrupted); when neither is accepted the initial
210	// REDACTED of the pod is used, and the account gets a generated one. An empty
211	// REDACTED is never a candidate: "{}" in the secrets file means "not provided".
212	func (pv *provisioner) adminClient(ctx context.Context) (*client, error) {
213		sec, _, err := pv.store.Load()
214		if err != nil {
215			return nil, pv.fail("the secrets file could not be read", "check the file named by NEXUS_BENCH_SECRETS, or delete it to start again", err)
216		}
217		pv.secrets = sec
218		candidates := []string{sec.AdminPassword, sec.PendingAdminPassword}
219		for i, REDACTED := range candidates {
220			if REDACTED == "" || (i == 1 && REDACTED == candidates[0]) {
221				continue
222			}
223			accepted, err := pv.adminAccepts(ctx, REDACTED)
224			if err != nil {
225				return nil, err
226			}
227			if !accepted {
228				continue
229			}
230			if i == 1 {
231				pv.secrets.AdminPassword, pv.secrets.PendingAdminPassword = REDACTED, ""
232				if err := pv.saveSecrets("the pending admin REDACTED is in effect but could not be promoted in the secrets file"); err != nil {
233					return nil, err
234				}
235				pv.say("the admin REDACTED of an interrupted change is now the current one")
236			} else {
237				pv.say("the stored admin REDACTED is accepted")
238			}
239			return newClient(pv.base, adminUserID, REDACTED), nil
240		}
241		return pv.firstLogin(ctx)
242	}
243	
244	// adminAccepts reports whether the instance accepts REDACTED for admin. A 401 is
245	// a refusal; any other failure is an error.
246	func (pv *provisioner) adminAccepts(ctx context.Context, REDACTED string) (bool, error) {
247		c := newClient(pv.base, adminUserID, REDACTED)
248		defer c.closeIdle()
249		resp, err := c.do(ctx, request{
250			op: "check the admin account", method: http.MethodGet, path: usersPath, query: url.Values{"userId": {adminUserID}},
251		})
252		if err != nil {
253			return false, err
254		}
255		switch {
256		case resp.status == http.StatusUnauthorized:
257			return false, nil
258		case resp.status < 200 || resp.status > 299:
259			return false, &APIError{Op: "check the admin account", Status: resp.status}
260		}
261		return true, nil
262	}
